new_cards = []
for definition in definitions:
    sid = definition['id']
    card = dict(definition)
    card.update(
        target_date='После аудита S17, до S18 и применимого внешнего срока',
        condition='always', stage='contest',
        handoff_path=f'memory/sessions/{sid}.md', evidence_dir=f'evidence/{sid}',
        planned_commit=f'slice({sid}): <конкретный результат>', acceptance_tag=f'slice/{sid}',
    )
    new_cards.append(card)
    state['slices'][sid] = dict(status='planned', commit_ref=None, handoff=card['handoff_path'], reason=None)
    for item in coverage['items']:
        if item['id'] in card['requirement_ids']:
            assert sid not in item['verification_slices']
            item['verification_slices'].append(sid)

